<script lang="ts">
import type { ApexConfig,ApexExperience,ApexLocale } from '../../../core/src/apex/mod.ts';
import type { createApexStore } from '../../../state/src/stores/apex.svelte.ts';
import { formatUSD } from '../../../core/src/apex/mod.ts';
import Booking from './Booking.svelte';
import Faq from './Faq.svelte';
import Gallery from './Gallery.svelte';
import { useResolver } from './url.ts';
let {config,experience,locale,store}:{config:ApexConfig;experience:ApexExperience;locale:ApexLocale;store:ReturnType<typeof createApexStore>}=$props();
const resolve = useResolver();
const ui=(es:string,en:string)=>locale==='es'?es:en;
const copy=(key:string,es:string,en:string)=>config.copy[key]?.[locale]??ui(es,en);
let flight=$derived(experience.kind==='flight');
let essentials=$derived(flight?[
{q:ui('Días y horarios','Days and times'),a:copy('flight_schedule','Indica tu fecha preferida. APEX confirmará días de operación, horario del vuelo y disponibilidad antes de reservar.','Share your preferred date. APEX will confirm operating days, flight time and availability before booking.')},
{q:ui('Llegada y preparación','Arrival and preparation'),a:copy('flight_arrival','La hora de llegada, el acceso al helipuerto y las indicaciones de embarque se confirman en tu propuesta.','Arrival time, heliport access and boarding instructions are confirmed in your proposal.')},
{q:ui('Requisitos para pasajeros','Passenger requirements'),a:copy('flight_requirements','Solicita los requisitos de identificación, edades y límites de peso del operador antes de contratar. No hay restricciones numéricas publicadas hasta su validación.','Ask for the operator’s identification, age and weight requirements before booking. Numeric restrictions are not published until validated.')},
{q:ui('Accesibilidad y asistencia','Accessibility and assistance'),a:copy('flight_accessibility','Comparte tus necesidades de asistencia para revisar la viabilidad antes de contratar.','Share any assistance needs so feasibility can be reviewed before booking.')},
{q:ui('Equipaje y objetos personales','Luggage and personal items'),a:copy('flight_luggage','Consulta con APEX las indicaciones del operador sobre equipaje y objetos personales.','Ask APEX for the operator’s instructions on luggage and personal items.')},
{q:ui('Clima y ajustes del vuelo','Weather and flight changes'),a:copy('flight_weather','La operación y la ruta deben confirmarse con el operador. Solicita las condiciones aplicables por clima, restricciones de vuelo y reprogramación antes de pagar.','Operations and route must be confirmed with the operator. Ask about weather, flight restrictions and rescheduling terms before paying.')},
{q:ui('Cambios y cancelaciones','Changes and cancellations'),a:copy('flight_cancellation','Los plazos, cargos y condiciones de devolución se incluirán en tu propuesta. Revísalos antes de aceptar; una solicitud no garantiza cupo ni confirma la reserva.','Deadlines, charges and refund terms are included in your proposal. Review them before accepting; an inquiry does not guarantee capacity or confirm a reservation.')}
]:[
{q:ui('Horario y programa','Schedule and program'),a:copy('marquesa_schedule','Jueves a domingo, con solicitud al menos 2 días antes. Inicio y recogida previstos a las 8:30 a. m., hora de Ciudad de México. El programa incluye ATV, caballos y tirolesa; acuerda el orden, la duración y la hora de regreso con APEX antes de contratar.','Thursday–Sunday, with inquiries at least 2 days ahead. Planned start and pickup at 8:30 a.m., Mexico City time. The program includes ATVs, horses and ziplining; agree on order, duration and return time with APEX before booking.')},
{q:ui('Incluido y servicios adicionales','Included and additional services'),a:copy('marquesa_inclusions','Las tres actividades forman parte de la experiencia privada para grupos de 2 a 6 personas. Transporte, alimentos y atención para celebraciones se detallan en la cotización; no los des por incluidos si no están expresamente confirmados.','All three activities form part of the private experience for groups of 2–6. Transport, food and celebration arrangements are detailed in the quote; do not assume they are included unless expressly confirmed.')},
{q:ui('Recogida y regreso','Pickup and return'),a:copy('marquesa_pickup','Indica los puntos que necesitas. APEX confirma cobertura, costo y ubicación exacta en la cotización. La dirección de la oficina no es el punto de encuentro del tour. La Marquesa se encuentra en el Estado de México, dentro de nuestra colección CDMX y alrededores.','Share the locations you need. APEX confirms coverage, cost and exact location in the quote. The office address is not the tour meeting point. La Marquesa is in the State of Mexico, within our CDMX and surroundings collection.')},
{q:ui('Antes de participar','Before participating'),a:copy('marquesa_requirements','Lleva pantalón largo, calzado cerrado con agarre y abrigo. Consulta con APEX los requisitos específicos de las actividades antes de contratar. Comparte cualquier necesidad de accesibilidad con el equipo para revisar la viabilidad.','Bring long trousers, closed shoes with grip and warm clothing. Ask APEX about specific activity requirements before booking. Share accessibility needs with the team so feasibility can be reviewed.')},
{q:ui('Cancelación y reprogramación','Cancellation and rescheduling'),a:copy('marquesa_cancellation','Solicita las condiciones aplicables a tu fecha y revísalas antes de aceptar la cotización o realizar un pago. Una consulta, una fecha seleccionada o un mensaje preparado no confirman la reserva.','Ask for the terms applicable to your date and review them before accepting a quote or making payment. An inquiry, selected date or prepared message does not confirm a reservation.')}
]);
let activityDescriptions=$derived(flight?[
copy('flight_activity_1','Contempla lugares históricos y edificios emblemáticos desde otra perspectiva. Los puntos de interés se confirman según la ruta de tu vuelo.','See historic places and iconic buildings from another perspective. Points of interest are confirmed according to your flight route.'),
copy('flight_activity_2','Descubre el contraste entre la ciudad, el valle y las montañas del horizonte. Las vistas naturales dependen de la ruta y de la visibilidad del día.','Discover the contrast between the city, valley and mountains on the horizon. Natural views depend on the route and visibility that day.'),
copy('flight_activity_3','Vive el despegue y disfruta las vistas desde la cabina. APEX confirma la aeronave, la duración y las indicaciones de embarque en tu propuesta.','Experience takeoff and enjoy the view from the cabin. APEX confirms the aircraft, duration and boarding instructions in your proposal.')
]:[
copy('marquesa_activity_1','Recorre los senderos en cuatrimoto y descubre el bosque desde el camino.','Ride the trails on an ATV and discover the forest from the path.'),
copy('marquesa_activity_2','Baja el ritmo. Conecta con el paisaje en un paseo a caballo.','Slow down. Connect with the landscape on a horseback ride.'),
copy('marquesa_activity_3','Dale un giro a tu día y completa la aventura al aire libre.','Give your day a twist and complete your outdoor adventure.')
]);
let activityImages=$derived(experience.activityImages ?? experience.gallery.slice(0,3));
let communityImages=$derived(experience.communityImages ?? experience.gallery.slice(0,3));
let questions=$derived(flight?[
{q:ui('¿Cómo se calcula el precio?','How is the price calculated?'),a:ui('La tarifa es por persona. APEX confirma moneda, impuestos, cargos y total para tu grupo antes de contratar.','The price is per person. APEX confirms currency, taxes, charges and the total for your group before booking.')},
{q:ui('¿Qué lugares veremos y cuánto dura?','What will we see and how long does it last?'),a:ui('La ruta, los puntos de interés y la duración se confirman en tu propuesta. Las imágenes son de referencia.','The route, points of interest and duration are confirmed in your proposal. Images are for reference.')},
{q:ui('¿El vuelo es privado?','Is the flight private?'),a:ui('La modalidad privada o compartida depende de la propuesta y de la aeronave disponible.','Private or shared arrangements depend on the proposal and available aircraft.')},
{q:ui('¿Incluye recogida en mi hotel?','Does it include hotel pickup?'),a:ui('Solicita el traslado al equipo. La cobertura y el costo se cotizan por separado, salvo inclusión expresa.','Request a transfer from the team. Coverage and cost are quoted separately unless expressly included.')},
{q:ui('¿Cómo confirmo mi reserva?','How do I confirm my reservation?'),a:ui('Completa la solicitud y envía el mensaje por WhatsApp. APEX revisará disponibilidad y enviará la propuesta con precio y condiciones. La reserva requiere confirmación expresa de APEX.','Complete the inquiry and send the message through WhatsApp. APEX will review availability and send a proposal with pricing and terms. The reservation requires explicit confirmation from APEX.')}
]:[
{q:ui('¿Qué incluye el tour?','What does the tour include?'),a:ui('El programa reúne recorrido en ATV, paseo a caballo y tirolesa. La duración, el orden y los requisitos de participación se confirman antes de reservar.','The program brings together ATV riding, horseback riding and ziplining. Duration, order and participation requirements are confirmed before booking.')},
{q:ui('¿Qué ropa debo usar?','What should I wear?'),a:essentials[3]?.a??''},
{q:ui('¿Qué días opera La Marquesa?','What days does La Marquesa operate?'),a:ui('La Marquesa opera de jueves a domingo. Consulta tu fecha con al menos 2 días de anticipación por WhatsApp; la selección del calendario no confirma disponibilidad. Para grupos grandes o eventos, solicita una propuesta a APEX.','La Marquesa operates Thursday–Sunday. Inquire about your date at least 2 days ahead through WhatsApp; selecting a calendar date does not confirm availability. Ask APEX for a proposal for larger groups or events.')},
{q:ui('¿La salida es privada?','Is the outing private?'),a:ui(`Sí. La experiencia está pensada para tu grupo. La tarifa inicia en ${formatUSD(config.prices[2],locale)} para dos personas y se ajusta al número de participantes, hasta seis. La disponibilidad se confirma al solicitar.`,`Yes. This experience is designed for your group. Prices start at ${formatUSD(config.prices[2],locale)} for two people and adjust to the number of participants, up to six. Availability is confirmed upon inquiry.`)},
{q:ui('¿Puedo organizar una celebración?','Can I organize a celebration?'),a:ui('Puedes solicitar atención para un cumpleaños, aniversario u otra ocasión. Confirmamos su viabilidad y cualquier costo adicional antes de que lo aceptes.','You may request help with a birthday, anniversary or another occasion. Feasibility and additional costs are confirmed before you accept.')},
{q:ui('¿Cómo funciona el pago en línea?','How does online payment work?'),a:ui('La contratación se coordina con APEX por WhatsApp. El cobro comercial en línea aún no está habilitado. Solicita con mínimo 2 días de anticipación y confirma disponibilidad con el equipo.','Booking is coordinated with APEX through WhatsApp. Commercial online charging is not enabled yet. Inquire at least 2 days ahead and confirm availability with the team.')},
{q:ui('¿Qué pasa si cambia el clima?','What happens if the weather changes?'),a:ui('APEX confirma contigo las condiciones de reprogramación y cancelación antes de tu salida. Consulta al equipo las condiciones aplicables a tu fecha.','APEX confirms rescheduling and cancellation terms with you before your outing. Ask the team for the conditions applicable to your date.')}
