<section id={flight?'vuelo-en-helicoptero':'la-marquesa'} class={flight?'wrap flight-intro svelte-1x3a6xm':'wrap tour-intro svelte-10d5s1j'}>
 <a class="back-link" href={flight ? resolve('/destinos/cdmx/') : resolve('/')}>← {flight?ui('Volver a explorar CDMX','Back to exploring CDMX'):ui('Volver a explorar','Back to exploring')}</a><div class={flight?'title-row svelte-1x3a6xm':'title-row svelte-10d5s1j'}><div><p class="eyebrow">{flight?ui('CDMX / EXPERIENCIA AÉREA','CDMX / AERIAL EXPERIENCE'):ui('ESTADO DE MÉXICO / EXPERIENCIA PRIVADA','STATE OF MEXICO / PRIVATE EXPERIENCE')}</p><div class="tour-badges"><span class="pill">{flight?ui('VUELO EN HELICÓPTERO','HELICOPTER FLIGHT'):ui('CONFIRMADA · Experiencia Insignia','CONFIRMED · Signature Experience')}</span></div><h1 class={flight?'svelte-1x3a6xm':'svelte-10d5s1j'}>{experience.title[locale]}<span class="apex-orange">.</span></h1></div><div class="apex-tour-summary"><p class="tour-price">{flight?ui('Tarifa por persona · Solicita cotización','Per-person price · Request a quote'):`${formatUSD(config.prices[2],locale)} ${ui('para dos personas · Español / Inglés','for two people · Spanish / English')}`}</p><p class="muted">{flight?experience.description[locale]:experience.meeting[locale]}</p></div></div>
 <div class={flight?'cover svelte-1x3a6xm':'tour-image svelte-10d5s1j'}><img class={flight?'svelte-1x3a6xm':'svelte-10d5s1j'} src={experience.image} alt={experience.title[locale]} fetchpriority="high"/><div class={flight?'cover-caption svelte-1x3a6xm':'image-caption svelte-10d5s1j'}><span>{flight?ui('CDMX / IMAGEN DE REFERENCIA','CDMX / REFERENCE IMAGE'):'APEX ORIGINAL / 01'}</span><a class="button" href={flight ? '#solicitar' : resolve('/reservar/')}>{ui('Consultar disponibilidad','Check availability')} ↗</a></div></div>
 <nav class="apex-tour-nav" aria-label={ui('En esta experiencia','In this experience')}><a href="#detalles">{ui('Qué incluye','What’s included')}</a>{#if flight}<a href="#operacion">{ui('Información práctica','Practical information')}</a><a href="#tarifa">{ui('Tarifa','Price')}</a><a href="#punto-de-encuentro">{ui('Punto de encuentro','Meeting point')}</a>{/if}<a href={flight?'#solicitar':'#reservar'}>{flight?ui('Planea tu vuelo','Plan your flight'):ui('Planea tu visita','Plan your visit')}</a><a href="#preguntas">{ui('Preguntas frecuentes','Frequently asked questions')}</a></nav>
</section>
<section id="detalles" class="section wrap"><div class="section-heading"><div><p class="eyebrow">{flight?ui('TU EXPERIENCIA EN EL AIRE','YOUR EXPERIENCE IN THE AIR'):ui('UN PROGRAMA. TRES ACTIVIDADES.','ONE PROGRAM. THREE ACTIVITIES.')}</p><h2>{flight?ui('La ciudad, desde otra perspectiva.','The city, from another perspective.'):ui('Cambia de ritmo.','Change your pace.')}</h2></div>{#if !flight}<p>{ui('Las tres actividades forman parte de la misma experiencia privada.','All three activities form part of the same private experience.')}</p>{/if}</div><div class={flight?'program svelte-1x3a6xm':'activities svelte-glb0fy'}>{#each experience.activities as activity,i}<article class={flight?'svelte-1x3a6xm':'svelte-glb0fy'}><img class={flight?'svelte-1x3a6xm':'svelte-glb0fy'} src={activityImages[i]} alt="" loading="lazy"/><div class={flight?'activity-marker svelte-1x3a6xm':'card-top svelte-glb0fy'}><span>{String(i+1).padStart(2,'0')} /</span></div><h3 class={flight?'svelte-1x3a6xm':'svelte-glb0fy'}>{activity[locale]}</h3><p class={flight?'svelte-1x3a6xm':'svelte-glb0fy'}>{activityDescriptions[i]}</p></article>{/each}</div><p class="notice apex-details-note">{flight?ui('El programa, la aeronave y los servicios se confirman en tu cotización. Las imágenes son de referencia.','The program, aircraft and services are confirmed in your quote. Images are for reference.'):ui('Antes de confirmar: revisa con APEX tarifa, duración, punto de encuentro, requisitos y condiciones de cancelación. Transporte, alimentos y servicios especiales se confirman en tu cotización.','Before confirming: review price, duration, meeting point, requirements and cancellation conditions with APEX. Transport, food and special services are confirmed in your quote.')}</p></section>
<section id="operacion" class={flight?'wrap section svelte-1x3a6xm':'wrap essentials svelte-1jp6tqk'}><h2 class={flight?'svelte-1x3a6xm':'svelte-1jp6tqk'}>{flight?ui('Tu vuelo, en breve.','Your flight, at a glance.'):ui('Tu salida, en breve.','Your outing, at a glance.')}</h2>{#if flight}<dl class="apex-flight-facts">{#each [ui('Tiempo de vuelo','Flight time'),ui('Duración total','Total duration'),ui('Pasajeros','Passengers'),ui('Modalidad','Arrangement'),ui('Idiomas','Languages'),ui('Anticipación','Advance notice')] as label,i}<div class="brand-panel"><dt>{label}</dt><dd>{[ui('Se confirma en tu propuesta','Confirmed in your proposal'),ui('Incluye tiempos previos; por confirmar','Includes preparation time; to be confirmed'),ui('Capacidad según aeronave','Capacity depends on aircraft'),ui('Privada o compartida: por confirmar','Private or shared: to be confirmed'),ui('Consulta el idioma disponible','Ask about available languages'),ui('Consulta para tu fecha','Inquire for your date')][i]}</dd></div>{/each}</dl>{/if}<div class={flight?'accordions svelte-1x3a6xm':'svelte-1jp6tqk'}>{#each essentials as item}<details class={flight?'brand-panel svelte-1x3a6xm':'brand-panel svelte-1jp6tqk'}><summary class={flight?'svelte-1x3a6xm':'svelte-1jp6tqk'}>{item.q}<span>+</span></summary><p class={flight?'svelte-1x3a6xm':'svelte-1jp6tqk'}>{item.a}</p></details>{/each}</div></section>
<div id="tarifa" class="booking-banner wrap brand-panel svelte-wb3hel"><div><p class="eyebrow">{ui('TU EXPERIENCIA, EN UNOS PASOS','YOUR EXPERIENCE, IN A FEW STEPS')}</p><h2 class="svelte-wb3hel">{flight?ui('Tarifa por persona · Solicita cotización','Per-person price · Request a quote'):ui('Primero, confirmemos tu salida.','First, let’s confirm your outing.')}</h2><p>{flight?ui('Tarifa por persona × número de pasajeros. Recibirás el total de tu grupo antes de confirmar. Moneda, impuestos y cargos se detallan en la cotización.','Per-person price × number of passengers. You receive your group total before confirming. Currency, taxes and charges are detailed in the quote.'):`${ui('Desde','From')} ${formatUSD(config.prices[2],locale)} ${ui('para dos personas · Español / Inglés. Solicita con mínimo 2 días de anticipación, sujeto a disponibilidad.','for two people · Spanish / English. Inquire at least 2 days ahead, subject to availability.')}`}</p></div><a class="button" href={flight ? '#solicitar' : resolve('/reservar/')}>{ui('Consultar disponibilidad','Check availability')} ↗</a></div>
<section id="punto-de-encuentro" class="wrap section tour-meeting"><p class="eyebrow">{flight?ui('DÓNDE COMIENZA TU EXPERIENCIA','WHERE YOUR EXPERIENCE BEGINS'):ui('DÓNDE VIVIRÁS LA EXPERIENCIA','WHERE YOU WILL EXPERIENCE THE ADVENTURE')}</p><h2>{experience.location[locale]}</h2><p class="muted">{experience.meeting[locale]}</p>{#if !flight&&experience.mapUrl}<a class="text-link" href={experience.mapUrl} target="_blank" rel="noopener noreferrer">{ui('Abrir ubicación en Google','Open location in Google')} ↗</a>{/if}</section>
<Booking {config} {locale} {store} experienceId={experience.id}/>
<section id="galeria" class="section wrap"><div class="section-heading"><div><p class="eyebrow">{flight?ui('UNA MIRADA A LA EXPERIENCIA','A LOOK AT THE EXPERIENCE'):ui('LA COMUNIDAD APEX','THE APEX COMMUNITY')}</p><h2>{flight?ui('Imagina tu próximo vuelo.','Imagine your next flight.'):ui('Las personas hacen la experiencia.','People make the experience.')}</h2></div><p>{flight?ui('Galería de referencia. No garantiza una aeronave ni un recorrido específico.','Reference gallery. It does not guarantee a specific aircraft or route.'):ui('Momentos reales compartidos con APEX. Detrás de cada salida, personas que buscan conectar, disfrutar y salir de la rutina.','Real moments shared with APEX. Behind every outing, people seeking connection, enjoyment and a break from routine.')}</p></div>{#if flight}<Gallery images={experience.gallery} title={experience.title[locale]} {locale} reducedMotion={store.reducedMotion}/><p class="small">{ui('Galería de referencia: vistas aéreas de CDMX y cabina fotografiada en Río de Janeiro. No garantiza una aeronave ni un recorrido específico.','Reference gallery: aerial views of CDMX and a cabin photographed in Rio de Janeiro. It does not guarantee a specific aircraft or route.')}</p>{:else}<div class="gallery svelte-c49bs4">{#each communityImages as image,i}<figure class="svelte-c49bs4"><button class="svelte-c49bs4" onclick={()=>{galleryIndex=i;galleryDialog.showModal();}} aria-label={ui(`Ampliar foto ${i+1}` ,`Enlarge photo ${i+1}`)}><img class="svelte-c49bs4" src={image} alt={[ui('Paseo a caballo en La Marquesa','Horseback riding in La Marquesa'),ui('Cuatrimotos frente al paisaje de La Marquesa','ATVs in the La Marquesa landscape'),ui('Un momento compartido durante la salida','A shared moment during the outing')][i]} loading="lazy"/></button><figcaption>{[ui('A otro ritmo','At a different pace'),ui('Fuera de lo de siempre','Beyond the everyday'),ui('Mejor, juntos','Better, together')][i]}</figcaption></figure>{/each}</div>{/if}</section>
<Faq {config} {locale} items={questions}/>
<dialog bind:this={galleryDialog} class="apex-lightbox" aria-label={ui('Fotografías de La Marquesa','La Marquesa photographs')}><button class="apex-lightbox-close" onclick={()=>galleryDialog.close()} aria-label={ui('Cerrar galería','Close gallery')}>×</button><img src={communityImages[galleryIndex]} alt={experience.title[locale]}/><div class="apex-lightbox-controls"><button onclick={()=>galleryIndex=(galleryIndex-1+communityImages.length)%communityImages.length} aria-label={ui('Fotografía anterior','Previous photograph')}>←</button><p>{galleryIndex+1} / {communityImages.length}</p><button onclick={()=>galleryIndex=(galleryIndex+1)%communityImages.length} aria-label={ui('Siguiente fotografía','Next photograph')}>→</button></div></dialog>
